import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 마감·승인 상태가 아닌 실행예산(신청·마감취소·승인취소)만 수정할 수 있다. 전환표에 수정 가능 상태가 없어 정한 값.
const EDITABLE_STATUS = ['신청', '마감취소', '승인취소'];

function textOf(v: unknown): string | null {
  if (v === undefined || v === null) {
    return null;
  }
  const s = String(v).trim();
  return s === '' ? null : s;
}

function intOf(v: unknown, name: string): string | null {
  const s = textOf(v);
  if (s === null) {
    return null;
  }
  if (!/^\d{1,15}$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바른 숫자가 아닙니다.');
  }
  return s;
}

function amountOf(v: unknown): string | null {
  if (typeof v !== 'number' && typeof v !== 'string') {
    return null;
  }
  const s = String(v).trim();
  if (!/^\d{1,16}(\.\d{1,2})?$/.test(s)) {
    return null;
  }
  return s;
}

@Controller('api/v1')
export class FnSfr00303Controller {
  @Get('/main-budgets/exec-targets')
  async listExecBudgetTargets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const page = Number(intOf(q['page'], 'page') ?? '0');
    const size = Number(intOf(q['size'], 'size') ?? String(DEFAULT_SIZE));
    if (size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상 ' + MAX_SIZE + ' 이하여야 합니다.');
    }
    const filter = {
      accountingUnit: textOf(q['accountingUnit']),
      fiscalYear: intOf(q['fiscalYear'], 'fiscalYear'),
      budgetGroup: textOf(q['budgetGroup']),
      budgetItemId: intOf(q['budgetItemId'], 'budgetItemId'),
      projectId: intOf(q['projectId'], 'projectId'),
    };
    // 승인된 본예산만 실행예산 신청 대상이다.
    const from = `FROM main_budget mb
      JOIN budget_item bi ON bi.budget_item_id = mb.budget_item_id
      WHERE mb.status = '승인'
      AND (CAST(:accountingUnit AS text) IS NULL OR mb.accounting_unit = CAST(:accountingUnit AS text))
      AND (CAST(:fiscalYear AS integer) IS NULL OR mb.fiscal_year = CAST(:fiscalYear AS integer))
      AND (CAST(:budgetGroup AS text) IS NULL OR bi.budget_group = CAST(:budgetGroup AS text))
      AND (CAST(:budgetItemId AS bigint) IS NULL OR mb.budget_item_id = CAST(:budgetItemId AS bigint))
      AND (CAST(:projectId AS bigint) IS NULL OR mb.project_id = CAST(:projectId AS bigint))`;
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT mb.main_budget_id AS "mainBudgetId",
          mb.budget_item_id AS "budgetItemId",
          mb.project_id AS "projectId",
          mb.request_amount AS "requestAmount"
          ${''}` + from + ` ORDER BY mb.main_budget_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filter, size: String(size), offset: String(page * size) },
      );
      const totals = await db.query('SELECT COUNT(*) AS "total" ' + from, filter);
      return { items, page, size, total: Number(totals[0].total) };
    });
  }

  @Post('/exec-budgets')
  @HttpCode(200)
  async createExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const mainBudgetId = textOf(data['mainBudgetId']);
    const month = textOf(data['budgetMonth']);
    const amount = amountOf(data['amount']);
    if (mainBudgetId === null || !/^\d{1,15}$/.test(mainBudgetId)) {
      throw new ApiError(422, 'EXEC_BUDGET_INVALID', '본예산 ID를 확인하세요.');
    }
    if (month === null || !/^\d{1,2}$/.test(month) || Number(month) < 1 || Number(month) > 12) {
      throw new ApiError(422, 'EXEC_BUDGET_INVALID', '편성 월은 1~12 사이여야 합니다.');
    }
    if (amount === null) {
      throw new ApiError(422, 'EXEC_BUDGET_INVALID', '실행예산 금액 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const mains = await db.query(
        'SELECT main_budget_id FROM main_budget WHERE main_budget_id = CAST(:mainBudgetId AS bigint) FOR UPDATE',
        { mainBudgetId },
      );
      if (mains.length === 0) {
        throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '기반 본예산을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT exec_budget_id FROM exec_budget WHERE main_budget_id = CAST(:mainBudgetId AS bigint) AND budget_month = CAST(:month AS integer)',
        { mainBudgetId, month },
      );
      if (dup.length > 0) {
        throw new ApiError(422, 'EXEC_BUDGET_INVALID', '이미 해당 월의 실행예산이 있습니다. 수정으로 처리하세요.');
      }
      const over = await db.query(
        `SELECT (COALESCE((SELECT SUM(e.amount) FROM exec_budget e WHERE e.main_budget_id = mb.main_budget_id), 0) + CAST(:amount AS numeric) > mb.request_amount) AS "exceeds"
         FROM main_budget mb WHERE mb.main_budget_id = CAST(:mainBudgetId AS bigint)`,
        { mainBudgetId, amount },
      );
      if (over[0].exceeds) {
        throw new ApiError(422, 'EXEC_BUDGET_EXCEEDS_MAIN', '월별 실행예산 합계가 본예산 금액을 초과합니다.');
      }
      const rows = await db.query(
        `INSERT INTO exec_budget (main_budget_id, budget_month, amount, status, created_at, updated_at)
         VALUES (CAST(:mainBudgetId AS bigint), CAST(:month AS integer), CAST(:amount AS numeric), '신청', now(), now())
         RETURNING exec_budget_id AS "execBudgetId", status AS "status"`,
        { mainBudgetId, month, amount },
      );
      return rows[0];
    });
  }

  @Put('/exec-budgets/:execBudgetId')
  async updateExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const execBudgetId = req.params['execBudgetId'];
    if (!/^\d{1,15}$/.test(execBudgetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실행예산 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const amount = amountOf(data['amount']);
    if (amount === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '실행예산 금액 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT main_budget_id AS "mainBudgetId", status AS "status"
         FROM exec_budget WHERE exec_budget_id = CAST(:execBudgetId AS bigint) FOR UPDATE`,
        { execBudgetId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EXEC_BUDGET_NOT_FOUND', '대상 실행예산을 찾을 수 없습니다.');
      }
      if (!EDITABLE_STATUS.includes(String(found[0].status))) {
        throw new ApiError(409, 'EXEC_BUDGET_CLOSED', '이미 마감된 실행예산입니다. 마감취소 후 수정하세요.');
      }
      const over = await db.query(
        `SELECT (COALESCE((SELECT SUM(e.amount) FROM exec_budget e WHERE e.main_budget_id = mb.main_budget_id AND e.exec_budget_id <> CAST(:execBudgetId AS bigint)), 0) + CAST(:amount AS numeric) > mb.request_amount) AS "exceeds"
         FROM main_budget mb WHERE mb.main_budget_id = CAST(:mainBudgetId AS bigint)`,
        { execBudgetId, amount, mainBudgetId: String(found[0].mainBudgetId) },
      );
      if (over.length > 0 && over[0].exceeds) {
        throw new ApiError(422, 'EXEC_BUDGET_EXCEEDS_MAIN', '월별 실행예산 합계가 본예산 금액을 초과합니다.');
      }
      const rows = await db.query(
        `UPDATE exec_budget SET amount = CAST(:amount AS numeric), updated_at = now()
         WHERE exec_budget_id = CAST(:execBudgetId AS bigint)
         RETURNING exec_budget_id AS "execBudgetId", status AS "status"`,
        { execBudgetId, amount },
      );
      return rows[0];
    });
  }
}

