import { useState } from 'react';
import { call, useData, Badge, Num, Filters, Band, DataTable, Pager, Drawer, Form, Field, TextInput, NumberInput, Select, LookupSelect, RefName } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const EDITABLE = ['신청', '마감취소', '승인취소'];
const MONTHS: [string, string][] = Array.from({ length: 12 }, (_, i): [string, string] => [String(i + 1), (i + 1) + '월']);

export default function FnSfr00303Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [results, setResults] = useState<Row[]>([]);
  const [createFor, setCreateFor] = useState<Row | null>(null);
  const [editing, setEditing] = useState<Row | null>(null);
  const [month, setMonth] = useState('');
  const [amount, setAmount] = useState<number | string>('');

  const list = useData<Page>(
    () => call<Page>('GET', '/main-budgets/exec-targets', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );

  const setField = (key: string, value: unknown) => setDraft({ ...draft, [key]: value });

  const openCreate = (row: Row) => {
    setMonth('');
    setAmount('');
    setCreateFor(row);
  };

  const openEdit = (row: Row) => {
    setAmount(row.amount as number);
    setEditing(row);
  };

  const submitCreate = async () => {
    if (!createFor) {
      return;
    }
    if (!month) {
      throw new Error('편성 월을 선택하세요.');
    }
    if (amount === '') {
      throw new Error('실행예산 금액을 입력하세요.');
    }
    const res = await call('POST', '/exec-budgets', role, {
      mainBudgetId: createFor.mainBudgetId,
      budgetMonth: Number(month),
      amount,
    });
    setResults([
      { ...res, mainBudgetId: createFor.mainBudgetId, budgetItemId: createFor.budgetItemId, budgetMonth: Number(month), amount },
      ...results,
    ]);
    notify('실행예산을 신청했습니다.');
    setCreateFor(null);
    list.reload();
  };

  const submitEdit = async () => {
    if (!editing) {
      return;
    }
    if (amount === '') {
      throw new Error('실행예산 금액을 입력하세요.');
    }
    const res = await call('PUT', '/exec-budgets/' + String(editing.execBudgetId), role, { amount });
    setResults(results.map((r) => (r.execBudgetId === editing.execBudgetId ? { ...r, ...res, amount } : r)));
    notify('실행예산을 수정했습니다.');
    setEditing(null);
    list.reload();
  };

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>신청 대상</h2>
        <Num value={total} />
      </section>
      <section className="box span-4">
        <h2>이번 신청</h2>
        <Num value={results.length} />
      </section>
      <section className="box span-4">
        <h2>신청 금액 합계</h2>
        <Num value={results.reduce((sum, r) => sum + Number(r.amount || 0), 0)} />
      </section>
      <section className="box span-8">
        <h2>신청 대상 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ ...draft });
          }}
          onReset={() => {
            setDraft({});
            setApplied({});
            setPage(0);
          }}
        >
          <Field label="회계단위">
            <TextInput value={draft.accountingUnit} onChange={(v) => setField('accountingUnit', v)} />
          </Field>
          <Field label="기수(회계연도)">
            <NumberInput value={draft.fiscalYear} onChange={(v) => setField('fiscalYear', v)} />
          </Field>
          <Field label="예산그룹">
            <TextInput value={draft.budgetGroup} onChange={(v) => setField('budgetGroup', v)} />
          </Field>
          <Field label="예산과목">
            <LookupSelect table="budget_item" role={role} value={draft.budgetItemId} onChange={(v) => setField('budgetItemId', v)} />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={draft.projectId} onChange={(v) => setField('projectId', v)} />
          </Field>
        </Filters>
        <Band total={total} />
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          empty="신청 대상이 없습니다."
          columns={[
            { key: 'mainBudgetId', label: '본예산 ID' },
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table="budget_item" role={role} value={r.budgetItemId} /> },
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table="project" role={role} value={r.projectId} /> },
            { key: 'requestAmount', label: '신청금액', render: (r) => <Num value={r.requestAmount} /> },
            { key: 'action', label: '편성', render: (r) => <button type="button" onClick={() => openCreate(r)}>월별 편성</button> },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>신청 결과</h2>
        <DataTable
          rows={results}
          empty="신청한 내역이 없습니다."
          columns={[
            { key: 'budgetMonth', label: '편성 월', render: (r) => <span>{String(r.budgetMonth)}월</span> },
            { key: 'amount', label: '실행예산 금액', render: (r) => <Num value={r.amount} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
            {
              key: 'action',
              label: '수정',
              render: (r) => (EDITABLE.includes(String(r.status)) ? <button type="button" onClick={() => openEdit(r)}>수정</button> : null),
            },
          ]}
        />
      </section>
      {createFor ? (
        <Drawer title="월별 실행예산 편성" onClose={() => setCreateFor(null)}>
          <Form onSubmit={submitCreate} submit="신청">
            <Field label="본예산 ID">
              <span>{String(createFor.mainBudgetId)}</span>
            </Field>
            <Field label="편성 월" required>
              <Select value={month} onChange={setMonth} options={MONTHS} />
            </Field>
            <Field label="실행예산 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {editing ? (
        <Drawer title="실행예산 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="편성 월">
              <span>{String(editing.budgetMonth)}월</span>
            </Field>
            <Field label="실행예산 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
